(async()=>{try{const urls=["flight-data-0.js", "flight-data-1.js", "flight-data-2.js", "flight-data-3.js", "flight-data-4.js", "flight-data-5.js", "flight-data-6.js"];await Promise.all(urls.map(url=>new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=url;s.onload=resolve;s.onerror=reject;document.body.appendChild(s);})));const packed=Uint8Array.from(atob(window.FlightData.join('')),c=>c.charCodeAt(0));const raw=await new Response(new Blob([packed]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();window.HelmetData=[btoa(Array.from(new Uint8Array(raw)).map(c=>String.fromCharCode(c)).join(''))];window.FlightData=null;const b=Uint8Array.from(atob(''),c=>c.charCodeAt(0));const t=await new Response(new Blob([b]).stream().pipeThrough(new DecompressionStream('gzip'))).text();const u=URL.createObjectURL(new Blob([t],{type:'text/javascript'}));const s=document.createElement('script');s.src=u;s.onload=()=>{URL.revokeObjectURL(u);window.HelmetScene?.mountHelmet(document.getElementById('helmet-model'));};document.body.appendChild(s);}catch(e){console.info('Optional effect unavailable',e);}})();
